"""Locale-independent day/month/year field with an optional native picker."""
def date_control(attrs):
    return f'''<div class="date-input"><input {attrs} type="text" inputmode="numeric" placeholder="dd/mm/rrrr" pattern="[0-9]{{2}}/[0-9]{{2}}/[0-9]{{4}}" maxlength="10" autocomplete="off" aria-describedby="date-format" title="Wpisz datę w formacie dd/mm/rrrr"><button id="date-picker-button" type="button" class="date-picker-button" aria-label="Wybierz datę z kalendarza" disabled><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg></button><input id="date-picker" class="date-picker-source" type="date" tabindex="-1" aria-hidden="true"></div><small id="date-format" class="field-hint">Format: dd/mm/rrrr</small>'''
